{
  "identity": {
    "name": "Ascending IT",
    "location": "2128 N Devlin Way, Nampa, ID 83687",
    "claims": [
      {
        "statement": "Ascending IT operates from a physical address at 2128 N Devlin Way, Nampa, ID 83687.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "Ascending IT provides IT management and cybersecurity services across the Treasure Valley and Boise area.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "With 20+ years of experience, Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      },
      {
        "statement": "Ascending IT also serves business clients nationwide.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "Delivering small business IT support in Boise and nationwide, with scalable solutions and expertise mid-sized businesses need to stay secure and supported."
      }
    ]
  },
  "industry": {
    "industry": "Managed IT Services and Cybersecurity (B2B Information Technology)",
    "activities": [
      "Managed IT services and 24/7 monitoring",
      "Cybersecurity services (EDR, anti-virus, ransomware protection, anti-phishing, dark web monitoring, security awareness training)",
      "Cloud and SaaS management",
      "IT infrastructure, patch, firewall, and network management",
      "Backup and disaster recovery",
      "Co-managed IT services and virtual CIO (vCIO) strategy",
      "Free IT assessments"
    ],
    "claims": [
      {
        "statement": "Ascending IT provides 24/7 monitoring, proactive maintenance, and IT support to businesses.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Our Boise Managed IT Services provide 24/7 monitoring, proactive maintenance, and fast support to reduce downtime, control costs, and keep your business running."
      },
      {
        "statement": "Ascending IT provides cybersecurity solutions against ransomware, phishing, and data breaches.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Defend your Boise business against ransomware, phishing, and data breaches with proactive cybersecurity solutions that protect sensitive data and client trust."
      },
      {
        "statement": "Ascending IT offers cloud and SaaS management, backup and disaster recovery, co-managed IT services, and strategy/vCIO services.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/managed-it-support-boise/",
        "quote": "Extend your in-house IT team with extra capacity, specialized skills, and 24/7 coverage when you need it most."
      },
      {
        "statement": "Ascending IT is a B2B managed service provider rather than a residential home-service contractor in HVAC, plumbing, or electrical trades.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "The official website presents tiered Managed IT service plans named Silver Package, Gold Package, and Platinum Package.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Silver Package Gold Package Platinum Package"
      },
      {
        "statement": "The company serves multiple commercial industries including Healthcare, Construction, Finance & Accounting, Professional Services, Manufacturing, Retail, and Hospitality.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Healthcare Construction Finance & Accounting Professional Services Manufacturing Retail Hospitality"
      },
      {
        "statement": "The website offers a free IT assessment as its primary lead generation call-to-action.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Start with a Free IT Assessment and get a clear picture of your strengths, risks, and opportunities for improvement."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Ascending IT states that it assists clients with industry regulatory compliance standards such as HIPAA and PCI-DSS.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "From HIPAA to PCI-DSS, and cybersecurity threats to scaling challenges, we provide proactive solutions that give you clarity and confidence."
      }
    ],
    "limitations": "No state business registration numbers, contractor licenses, or specific vendor certification numbers are published on the pages read."
  },
  "existingSoftware": [
    {
      "product": "on-sitesvcs.connectboosterportal.com",
      "purpose": "Referenced host on the website for client payment portal functionality",
      "evidence": {
        "statement": "The homepage references the external host on-sitesvcs.connectboosterportal.com.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "on-sitesvcs.connectboosterportal.com"
      }
    },
    {
      "product": "onsitesvcs.itclientportal.com",
      "purpose": "Referenced host on the website for client ticket status portal functionality",
      "evidence": {
        "statement": "The homepage references the external host onsitesvcs.itclientportal.com.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "onsitesvcs.itclientportal.com"
      }
    },
    {
      "product": "fluentform (ascending-it.com/wp-content/plugins/fluentform)",
      "purpose": "Web form submission script on the company website",
      "evidence": {
        "statement": "The website loads a script from /wp-content/plugins/fluentform/assets/js/form-submission.js.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://ascending-it.com/wp-content/plugins/fluentform/assets/js/form-submission.js?ver=6.2.16"
      }
    },
    {
      "product": "Divi / diviflash / divi-toolbox",
      "purpose": "Website theme and frontend layout scripts",
      "evidence": {
        "statement": "The website loads scripts from /wp-content/themes/Divi/js/scripts.min.js.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://ascending-it.com/wp-content/themes/Divi/js/scripts.min.js?ver=4.27.9"
      }
    },
    {
      "product": "cdn-cookieyes.com",
      "purpose": "Cookie consent banner script",
      "evidence": {
        "statement": "The website loads a script from https://cdn-cookieyes.com/client_data/75571865f9d74371b7690cb1/script.js.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://cdn-cookieyes.com/client_data/75571865f9d74371b7690cb1/script.js"
      }
    },
    {
      "product": "googletagmanager.com",
      "purpose": "Website tag and analytics management script",
      "evidence": {
        "statement": "The website loads a script from https://www.googletagmanager.com/gtag/js?id=G-MDX53VR4NQ.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=G-MDX53VR4NQ"
      }
    },
    {
      "product": "policies.termageddon.com",
      "purpose": "Embedded policy loading script on the Terms page",
      "evidence": {
        "statement": "The Terms page loads a script from https://policies.termageddon.com/api/embed/ZUhCUFNVVjBkMjFITWxNMloyYzlQUT09.js.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/terms/",
        "quote": "https://policies.termageddon.com/api/embed/ZUhCUFNVVjBkMjFITWxNMloyYzlQUT09.js"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Ascending IT already operates client portals for making payments and viewing ticket status.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/",
      "quote": "RESOURCES Make A Payment View Ticket Status"
    },
    {
      "statement": "Ascending IT sells IT management, automated email threat remediation for 365/Google Workspace, and SaaS active monitoring to its own clients.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/",
      "quote": "*Automated Email Threat Remediation is for 365/Google Workspace"
    }
  ],
  "problems": [
    {
      "problem": "No operational problems relevant to ForgeX's home-service contractor offerings are observable on the public website.",
      "label": "inference",
      "basis": "Based on https://ascending-it.com/ and https://ascending-it.com/managed-it-support-boise/, Ascending IT is a Managed IT Service Provider (MSP) with its own technical staff, ticketing portal, payment portal, and 24/7 monitoring capabilities."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Client ticketing and payment portals (onsitesvcs.itclientportal.com and on-sitesvcs.connectboosterportal.com)",
      "addresses": "Customer support ticket tracking and billing/payment collection",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Ascending IT is a B2B Managed IT Services and Cybersecurity provider outside ForgeX's target segment of home-service contractors."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Pursue-level outreach to an IT managed services provider for contractor-focused field-service automation would be misaligned with their business model and internal technical capabilities."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website does not publish dollar prices for its Silver, Gold, or Platinum packages, stating instead that pricing depends on the number of users, devices, and services needed.",
      "Because the company is outside ForgeX's target segment and no prices are shown on the site, commercial value is not calculated."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Founder",
      "Managing Partner / President"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ascending-it.com/",
        "usedFor": "Business identity, Nampa address, phone number, core IT and cybersecurity services, service packages, and referenced portal/script hosts."
      },
      {
        "url": "https://ascending-it.com/boise-it-company/",
        "usedFor": "Company mission, nationwide service scope, and compliance support details."
      },
      {
        "url": "https://ascending-it.com/it-support-boise/",
        "usedFor": "Contact information, 24/7 support availability, and contact form verification."
      },
      {
        "url": "https://ascending-it.com/terms/",
        "usedFor": "Checking terms page for legal entity name or registration details and embedded scripts."
      },
      {
        "url": "https://ascending-it.com/managed-it-support-boise/",
        "usedFor": "Detailed breakdown of managed IT services, co-managed IT, vCIO offerings, and pricing structure explanation."
      },
      {
        "url": "https://ascending-it.com/cybersecurity-services-boise/",
        "usedFor": "Detailed breakdown of cybersecurity services and compliance offerings."
      }
    ],
    "limitations": [
      "The website does not name any owners, executives, or managers on the pages read.",
      "The website does not disclose employee headcount or service pricing figures.",
      "The Terms and Conditions page dynamically loads policy text via a third-party script (policies.termageddon.com) which does not render static text in the fetcher."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX targets owner-led home-service contractors (HVAC, plumbing, and electrical) with 10 to 75 staff. Ascending IT is a B2B Managed IT Services and Cybersecurity provider (MSP) that manages IT infrastructure, cloud systems, and security for commercial clients and already operates its own ticketing and payment portals."
  }
}
